SELECT id, scan_batch_id AS scanBatchId, shelve_id AS shelveId, campus_name AS campusName, room_id AS roomId, room_name AS roomName, position_x AS positionX, position_y AS positionY, position_label AS positionLabel, status_code AS statusCode, status_label AS statusLabel, pi_name AS piName, department_name AS departmentName, project_pi_name AS projectPiName, detail_name AS detailName, detail_description AS detailDescription, cage_box_qr_code AS cageBoxQrCode, animal_cage_type AS animalCageType, scanned_at AS scannedAt FROM cage_special_status_snapshot WHERE scan_batch_id = #{scanBatchId}
AND status_code = #{statusCode}
ORDER BY room_name, shelve_id, position_y, position_x
LIMIT #{limit} OFFSET #{offset}
